/photos/farmington.webp" srcset="/assets/img/photos/farmington-640.webp 640w, /assets/img/photos/farmington.webp 1200w" sizes="(max-width:760px) 50vw, 300px" width="1200" height="800" alt="" loading="lazy" decoding="async"><span><b>Farmington</b><small>San Juan County</small></span></a><a class="ccard rv" href="/cities-we-serve/hobbs/"><img src="/assets/img/photos/oilfield.webp" srcset="/assets/img/photos/oilfield-640.webp 640w, /assets/img/photos/oilfield.webp 1200w" sizes="(max-width:760px) 50vw, 300px" width="1200" height="800" alt="" loading="lazy" decoding="async"><span><b>Hobbs</b><small>Lea County</small></span></a><a class="ccard rv" href="/cities-we-serve/clovis/"><img src="/assets/img/photos/plains-farm.webp" srcset="/assets/img/photos/plains-farm-640.webp 640w, /assets/img/photos/plains-farm.webp 1014w" sizes="(max-width:760px) 50vw, 300px" width="1014" height="676" alt="" loading="lazy" decoding="async"><span><b>Clovis</b><small>Curry County</small></span></a><a class="ccard rv" href="/cities-we-serve/carlsbad/"><img src="/assets/img/photos/carlsbad-caverns.webp" srcset="/assets/img/photos/carlsbad-caverns-640.webp 640w, /assets/img/photos/carlsbad-caverns.webp 1024w" sizes="(max-width:760px) 50vw, 300px" width="1024" height="683" alt="" loading="lazy" decoding="async"><span><b>Carlsbad</b><small>Eddy County</small></span></a><a class="ccard rv" href="/cities-we-serve/alamogordo/"><img src="/assets/img/photos/dust-storm.webp" srcset="/assets/img/photos/dust-storm-640.webp 640w, /assets/img/photos/dust-storm.webp 946w" sizes="(max-width:760px) 50vw, 300px" width="946" height="631" alt="" loading="lazy" decoding="async"><span><b>Alamogordo</b><small>Otero County</small></span></a><a class="ccard rv" href="/cities-we-serve/los-alamos/"><img src="/assets/img/photos/los-alamos.webp" srcset="/assets/img/photos/los-alamos-640.webp 640w, /assets/img/photos/los-alamos.webp 1200w" sizes="(max-width:760px) 50vw, 300px" width="1200" height="800" alt="" loading="lazy